<?php

namespace Database\Factories;

use App\Enums\WidgetAppearance;
use App\Enums\WidgetLayout;
use App\Models\Space;
use App\Models\Widget;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends Factory<Widget>
 */
class WidgetFactory extends Factory
{
    /**
     * The name of the factory's corresponding model.
     *
     * @var class-string<Widget>
     */
    protected $model = Widget::class;

    /**
     * Define the model's default state.
     *
     * The public id is not set here: it is generated by the model, so a
     * widget created through any path gets one.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'space_id' => Space::factory(),
            'layout' => WidgetLayout::Masonry,
            'theme' => WidgetAppearance::Light,
            'background' => null,
            'animation' => true,
            'limit' => 6,
        ];
    }

    /**
     * The widget shows its testimonials side by side in a row.
     */
    public function carousel(): static
    {
        return $this->state(fn (array $attributes): array => [
            'layout' => WidgetLayout::Carousel,
        ]);
    }

    /**
     * The widget is shown in dark mode.
     */
    public function dark(): static
    {
        return $this->state(fn (array $attributes): array => [
            'theme' => WidgetAppearance::Dark,
        ]);
    }
}
